class ConnectGame:
    def __init__(self, board):
        self.board = [line.split() for line in board.splitlines() if line.strip()]
        self.height = len(self.board)
        self.width = len(self.board[0]) if self.board else 0

    def get_winner(self):
        if self._has_connection("X"):
            return "X"
        if self._has_connection("O"):
            return "O"
        return ""

    def _has_connection(self, player):
        if player == "X":
            # X plays left to right: start on the left edge, target the right edge.
            start = [(r, 0) for r in range(self.height) if self.board[r][0] == player]
            target = lambda r, c: c == self.width - 1
        else:
            # O plays top to bottom: start on the top edge, target the bottom edge.
            start = [(0, c) for c in range(self.width) if self.board[0][c] == player]
            target = lambda r, c: r == self.height - 1

        if not start:
            return False

        visited = set(start)
        stack = list(start)
        while stack:
            r, c = stack.pop()
            if target(r, c):
                return True
            for neighbor in self._neighbors(r, c):
                if neighbor not in visited and self.board[neighbor[0]][neighbor[1]] == player:
                    visited.add(neighbor)
                    stack.append(neighbor)
        return False

    def _neighbors(self, r, c):
        # Hexagonal adjacency: left, right, and the four diagonal directions.
        for dr, dc in ((0, -1), (0, 1), (-1, -1), (-1, 0), (1, 0), (1, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < self.height and 0 <= nc < self.width:
                yield nr, nc

